#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <stdlib.h>
#include <pthread.h>

#define N 61440000
#define NTHREADS 12

static unsigned char key[16], nonce[12];
static unsigned char *pt, *ct;
static size_t chunk;

void* ctr_worker(void* arg){
    long id = (long)arg;
    size_t start = id*chunk;
    size_t len = (id==NTHREADS-1)? (N-start) : chunk;
    unsigned char counter[16];
    memcpy(counter, nonce, 12);
    // counter = nonce || 0x00000002 + block index
    unsigned int ctr = 2 + (unsigned int)(start/16);
    counter[12]=ctr>>24; counter[13]=ctr>>16; counter[14]=ctr>>8; counter[15]=ctr;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_ctr(), NULL, key, counter);
    int outl;
    EVP_EncryptUpdate(ctx, ct+start, &outl, pt+start, len);
    EVP_EncryptFinal_ex(ctx, ct+start+outl, &outl);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main(){
    pt = malloc(N); ct = malloc(N);
    RAND_bytes(key,16); RAND_bytes(nonce,12); RAND_bytes(pt,N);
    chunk = N/NTHREADS;
    // warm
    pthread_t th[NTHREADS];
    for(long i=0;i<NTHREADS;i++) pthread_create(&th[i],NULL,ctr_worker,(void*)i);
    for(int i=0;i<NTHREADS;i++) pthread_join(th[i],NULL);

    struct timespec t0,t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    for(int r=0;r<5;r++){
        for(long i=0;i<NTHREADS;i++) pthread_create(&th[i],NULL,ctr_worker,(void*)i);
        for(int i=0;i<NTHREADS;i++) pthread_join(th[i],NULL);
    }
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double dt = (t1.tv_sec-t0.tv_sec)+(t1.tv_nsec-t0.tv_nsec)/1e9;
    printf("parallel CTR: %.4f s, %.1f MB/s\n", dt/5, N/(dt/5)/1e6);
    return 0;
}
EOF
